import React from 'react';

const styles = {
  container: {
    padding: '40px 20px',
    maxWidth: '800px',
    margin: '0 auto',
    lineHeight: '1.6',
  },
  heading: {
    fontSize: '2rem',
    marginBottom: '20px',
    textAlign: 'center',
  },
  paragraph: {
    marginBottom: '15px',
  }
};

const TermsAndConditions = () => {
  return (
    <div style={styles.container}>
      <h1 style={styles.heading}>Terms and Conditions</h1>
      <p style={styles.paragraph}>
        Welcome to Karpagam Clinic. If you continue to browse and use this website, you are agreeing to comply with and be bound by the following terms and conditions of use, which together with our privacy policy govern Karpagam Clinic's relationship with you in relation to this website.
      </p>
      <p style={styles.paragraph}>
        The term 'Karpagam Clinic' or 'us' or 'we' refers to the owner of the website. The term 'you' refers to the user or viewer of our website.
      </p>
      <p style={styles.paragraph}>
        The use of this website is subject to the following terms of use:
      </p>
      <ul>
        <li>The content of the pages of this website is for your general information and use only. It is subject to change without notice.</li>
        <li>This website uses cookies to monitor browsing preferences. If you do allow cookies to be used, the following personal information may be stored by us for use by third parties.</li>
        <li>Neither we nor any third parties provide any warranty or guarantee as to the accuracy, timeliness, performance, completeness or suitability of the information and materials found or offered on this website for any particular purpose.</li>
      </ul>
      {/* Add more terms and conditions text as needed */}
    </div>
  );
};

export default TermsAndConditions;
